frappe.ui.form.on('Beneficiaries Registration', {
    onload: function(frm) {
        // Store initial field values for comparison
        frm.initialFieldValues = Object.assign({}, frm.doc);
    },
    validate: function(frm) {
        // Compare current field values with initial values
        let isChanged = Object.keys(frm.doc).some(field => frm.initialFieldValues[field] !== frm.doc[field]);

        if (isChanged && frm.doc.status === 'Not Accepted') {
            // Trigger the "Submit" action
            frappe.call({
                method: 'frappe.model.workflow.apply_workflow',
                args: {
                    'doc': frm.doc,
                    'action': 'Submit'
                },
                callback: function(response) {
                    if (!response.exc) {
                        frappe.msgprint('Document submitted successfully');
                        frm.reload_doc();
                    } else {
                        console.log('Submit action failed', response.exc);
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Beneficiary Request', {
    onload: function(frm) {
        // Check if the document is new (unsaved) and if a beneficiary is selected
        if (frm.doc.__islocal && frm.doc.beneficiary) {
            // Fetch the beneficiary's name using frappe.db.get_value
            frappe.db.get_value('Beneficiary', frm.doc.beneficiary, 'beneficiary_name', function(res) {
                if (res && res.beneficiary_name) {
                    // Set the beneficiary name to the field so that it appears on the form
                    frm.set_value('beneficiary_name', res.beneficiary_name);
                }
            });
        }
    }
});

frappe.ui.form.on("Beneficiaries Registration", {
    onload: function(frm) {
        setTimeout(function() {
            var isNotAccepted = frm.doc.status === "Not Accepted";

            if (isNotAccepted) {
                frm.set_df_property("rejection_note", "hidden", 0);
                frappe.msgprint("You need to fill the rejection note.");
            } else {
                frm.set_df_property("rejection_note", "hidden", 1);
            }
        }, 100); // Delay execution for 100 milliseconds
    }
});

frappe.ui.form.on('Beneficiaries Registration', {
    refresh: function(frm) {
        if (frm.doc.workflow_state === 'Accepted') {
            frm.fields.forEach(function(field) {
                if (field.df.fieldname !== "custom_notes") {
                    field.df.read_only = 1;
                }
            });
            frm.refresh_fields();
        } else {
            frm.fields.forEach(function(field) {
                field.df.read_only = 0;
            });
            frm.refresh_fields();
        }
    },
    
    before_save: function(frm) {
        if (frm.doc.workflow_state === 'Accepted' && frm.doc.custom_notes === "") {
            frappe.msgprint(__('Cannot save the document in "Accepted" state.'));
            frappe.validated = false;
        }
    }
});

