function promptRejectionReasonAndCreateNote(frm) {
    frappe.prompt(
        [
            {
                label: 'Rejection Note Reason',
                fieldname: 'rejection_reason',
                fieldtype: 'Text',
                reqd: 1
            }
        ],
        function(values) {
            // Create a new Rejection Note document on the client side
            var rejection_note = frappe.model.get_new_doc('Rejection Note');
            rejection_note.beneficiaries_rejection = frm.doc.name;
            rejection_note.rejection_note = values.rejection_reason;
            // Set other relevant fields as needed

            // Insert the Rejection Note document into the local database
            frappe.db.insert(rejection_note).then(function(response) {
                if (response.exc) {
                    frappe.msgprint('Error: ' + response.exc);
                } else {
                    frappe.msgprint('Rejection Note inserted successfully.');
                    
                    // Now submit the Rejection Note
                    frappe.call({
                        method: 'frappe.client.submit',
                        args: {
                            doc: response
                        },
                        callback: function(r) {
                            if (!r.exc) {
                                frappe.msgprint('Rejection Note submitted successfully.');
                                
                                // Reload the Beneficiaries Registration document
                                cur_frm.reload_doc();
                            } else {
                                frappe.msgprint('Error: ' + r.exc);
                            }
                        }
                    });
                    
                }
            });
        },
        'Create Rejection Note'
    );
}

frappe.ui.form.on('Beneficiaries Registration', {

    validate: function(frm) {
        let dob = frm.doc.date_of_birth;
        if (dob) {
            let today = new Date();
            let birthDate = new Date(dob);
            let age = today.getFullYear() - birthDate.getFullYear();

            let monthDifference = today.getMonth() - birthDate.getMonth();
            if (monthDifference < 0 || (monthDifference === 0 && today.getDate() < birthDate.getDate())) {
                age--;
            }

            if (age < 21) {
                frappe.msgprint('Must be 21 years of age or older.');
                frm.set_value('date_of_birth', '');
                frappe.validated = false;
            }
        }
    }

})
